package kube_test

import (
	"encoding/json"
	"testing"

	"github.com/spacechunks/control-plane/internal/service/server/kube"
	"github.com/stretchr/testify/require"
)

func TestClusterSetUnmarshalJSON(t *testing.T) {
	data := `
{
  "dev": "apiVersion: v1\nkind: Config\nclusters:\n- name: dev\n  cluster:\n    server: https://dev.k8s.example.internal:6443\n    certificate-authority-data: \nusers:\n- name: dev-admin\n  user:\n    token: dev-test-token-0123456789abcdef\ncontexts:\n- name: dev\n  context:\n    cluster: dev\n    user: dev-admin\n    namespace: default\ncurrent-context: dev\n",
  "prod": "apiVersion: v1\nkind: Config\nclusters:\n- name: prod\n  cluster:\n    server: https://prod.k8s.example.internal:6443\n    certificate-authority-data: \nusers:\n- name: prod-admin\n  user:\n    client-certificate-data: \n    client-key-data: \ncontexts:\n- name: prod\n  context:\n    cluster: prod\n    user: prod-admin\n    namespace: default\ncurrent-context: prod\n"
}
`
	var set kube.ClusterSet
	err := json.Unmarshal([]byte(data), &set)
	require.NoError(t, err)
}
